import torch
from torch import nn

class Conv2d(nn.Module):
    def __init__(self, in_channels=3, out_channels=16, kernel_size=3, padding=1):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=padding)
    def forward(self, x):
        return self.conv(x)

import torch
from torch import nn

class CNN(nn.Module):
    def __init__(self, in_channels=3, out_channels=16, kernel_size=3):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=1)
        self.act = nn.ReLU()
        self.pool = nn.MaxPool2d(2)
    def forward(self, x):
        return self.pool(self.act(self.conv(x)))

import torch
from torch import nn

class FeedForward(nn.Module):
    def __init__(self, width=64, hidden=256):
        super().__init__()
        self.first = nn.Linear(width, hidden)
        self.act = nn.ReLU()
        self.last = nn.Linear(hidden, width)
    def forward(self, x):
        return self.last(self.act(self.first(x)))

import torch
from torch import nn

class Residual(nn.Module):
    def __init__(self, width=64):
        super().__init__()
        self.proj = nn.Linear(width, width)
        self.norm = nn.LayerNorm(width)
    def forward(self, x):
        return self.norm(x + self.proj(x))

